// Exercise multiple overloads of phmap::erase_if with predicates that selectively remove elements
{
    const int (*ints)[16] = FUZZ_PARAM(int[16]);
    const int (*ints2)[16] = FUZZ_PARAM(int[16]);
    auto n1 = (size_t)(*FUZZ_PARAM(unsigned int) % 16);
    auto n2 = (size_t)(*FUZZ_PARAM(unsigned int) % 16);
    unsigned mod = (unsigned)(*FUZZ_PARAM(unsigned int) % 7u) + 1u; // non-zero to avoid div-by-zero
    unsigned mod2 = (unsigned)(*FUZZ_PARAM(unsigned int) % 7u) + 1u;

    // 1) btree_set<int>
    phmap::btree_set<int> s;
    for (size_t i = 0; i < n1; ++i) s.insert((*ints)[i]);
    auto pred_set = [&](const int &k){ return ((unsigned)(k >= 0 ? k : -k) % mod) == (mod - 1u); };
    // Pre-validate: after erasure, no element should satisfy pred
    phmap::erase_if(s, pred_set);
    for (const auto &k : s) {
        FUZZ_ASSERT(!pred_set(k), "btree_set erase_if left a matching element");
    }

    // 2) btree_multiset<int>
    phmap::btree_multiset<int> ms;
    for (size_t i = 0; i < n2; ++i) ms.insert((*ints2)[i] / 2); // allow duplicates
    auto pred_mset = [&](const int &k){ return ((unsigned)(k >= 0 ? k : -k) % mod2) == 0u; };
    phmap::erase_if(ms, pred_mset);
    for (const auto &k : ms) {
        FUZZ_ASSERT(!pred_mset(k), "btree_multiset erase_if left a matching element");
    }

    // 3) btree_map<int, std::string>
    std::string base = FUZZ_PARAM_STR();
    auto mk_str = [&](int v){
        size_t n = base.size();
        if (n == 0) return std::string();
        size_t pos = (size_t)(v >= 0 ? v : -v) % n;
        size_t len = (size_t)(1 + ((unsigned)pos % std::min<size_t>(16, n)));
        return base.substr(pos, std::min(len, n - pos));
    };
    phmap::btree_map<int, std::string> mp;
    for (size_t i = 0; i < n1; ++i) mp.emplace((*ints)[i], mk_str((*ints)[i]));
    unsigned key_mod = (unsigned)(*FUZZ_PARAM(unsigned int) % 5u) + 1u;
    size_t min_len = (size_t)(*FUZZ_PARAM(unsigned int) % 8u);
    auto pred_map = [&](const std::pair<const int, std::string> &kv){
        return ((unsigned)(kv.first >= 0 ? kv.first : -kv.first) % key_mod) == 0u || kv.second.size() < min_len;
    };
    phmap::erase_if(mp, pred_map);
    for (const auto &kv : mp) {
        FUZZ_ASSERT(!pred_map(kv), "btree_map erase_if left a matching element");
    }
}
