    bool make_null = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
    std::unique_ptr<int, Deleter> up(make_null ? nullptr : new int((int)*FUZZ_PARAM(int)));
    std::shared_ptr<int> sp = phmap::ShareUniquePtr(std::move(up));
    // Postconditions: moved-from unique_ptr becomes empty; shared_ptr owns pointer if non-null.
    FUZZ_ASSERT(!up, "unique_ptr should be empty after ShareUniquePtr move");
    if (sp) { (void)*sp; FUZZ_ASSERT(sp.use_count() >= 1, "shared_ptr use_count must be >= 1 when non-null"); }
}
