// Copy from initialized source range into uninitialized destination using allocator.
{
    struct T { int v; T()=default; T(const T& o):v(o.v){} T(int x):v(x){} };
    using Alloc = std::allocator<T>;
    Alloc alloc;
    std::size_t n = (std::size_t)(*FUZZ_PARAM(unsigned int) % 16u + 1u);
    // Prepare source values
    std::vector<T> src; src.reserve(n);
    int seed = (int)*FUZZ_PARAM(int);
    for (std::size_t i = 0; i < n; ++i) src.emplace_back(seed + (int)i);
    // Allocate destination uninitialized storage
    T* dst = phmap::allocator_traits<Alloc>::allocate(alloc, n);
    phmap::memory_internal::CopyRange(alloc, dst, src.begin(), src.end());
    for (std::size_t i = 0; i < n; ++i) { FUZZ_ASSERT(dst[i].v == src[i].v, "CopyRange value mismatch"); }
    // Destroy destination objects and deallocate storage
    for (std::size_t i = 0; i < n; ++i) phmap::allocator_traits<Alloc>::destroy<T>(alloc, &dst[i]);
    phmap::allocator_traits<Alloc>::deallocate(alloc, dst, n);
}
