            return h;
        }
        static H combine_contiguous(H h, const int* p, size_t n) {
            const unsigned char* b = reinterpret_cast<const unsigned char*>(p);
            size_t bytes = n * sizeof(int);
            size_t acc = h.v;
            // Mix up to 512 bytes for speed; safe for null when bytes==0
            for (size_t i = 0; i < bytes && i < 512; ++i) {
