unsigned int off = *FUZZ_PARAM(unsigned int) % (16 - sizeof(uint16_t) + 1);
uint16_t val = *FUZZ_PARAM(uint16_t);
phmap::big_endian::Store16(buf + off, val);
uint16_t r = phmap::big_endian::Load16(buf + off);
FUZZ_ASSERT(r == val, "Load16 must read back the value written by Store16 (big-endian path)");
/* OK: Ensured readable bytes and round-trip via BE helpers; no outputs. */

